const item = $input.first().json;
const body = item.body || item;
return [{ json: {
  sessionId: body.sessionId || 'anonymous',
  message: body.message || '',
  pageUrl: body.pageUrl || '',
  history: Array.isArray(body.history) ? body.history : [],
}}];

const incoming = $input.first().json;
const history = incoming.history || [];
const historyText = history.slice(-12).map((msg) => `${msg.role}: ${msg.content}`).join('
');
const websiteContext = `Clinic name: Pearl Dental Studio.
Services: Dental Implants, Teeth Whitening, Braces, Root Canal, Dental Fillings, Bonding.
Positioning: Modern, clean, friendly dental clinic for consultation-first dental care.
Goal: Help visitors with general service questions and capture leads for staff follow-up.
Safety: Do not diagnose, prescribe, guarantee treatment, give emergency medical advice, or replace a dentist consultation. For pain, swelling, bleeding, trauma, fever, or urgent symptoms, advise contacting a dentist or emergency service promptly.`;
const agentInput = `Current visitor message: ${incoming.message}
Page URL: ${incoming.pageUrl}
Session ID: ${incoming.sessionId}
Conversation history:
${historyText}
Website information:
${websiteContext}

Required lead fields in this exact order: service, name, email, phone.
Conversation rules:
1. If user sends a normal greeting or general message, reply with a greeting/answer and end with: What service are you looking for?
2. Collect only one missing field at a time. Do not ask for name, email, and phone in one message.
3. First identify service. Then ask name. After name ask email. After email ask phone number.
4. When service, name, email, and phone are all known, say: Our team will follow back soon.
5. Return ONLY valid JSON text. Do not use markdown. Do not call tools. Do not wrap in code fences.
JSON shape: {"reply":"string","lead":{"name":"","phone":"","email":"","service":"","notes":""},"leadComplete":false,"missingFields":["service","name","email","phone"]}`;
return [{ json: { ...incoming, agentInput } }];

const source = $('Prepare Agent Input').first().json;
let raw = $input.first().json.output || '{}';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.replace(/```json|```/g, '').trim();
let output;
try { output = JSON.parse(raw); } catch (error) { output = { reply: 'Hello! What service are you looking for?', lead: {}, leadComplete: false, missingFields: ['service', 'name', 'email', 'phone'] }; }
const lead = output.lead || {};
const required = ['service', 'name', 'email', 'phone'];
const missingFields = required.filter((field) => !String(lead[field] || '').trim());
const leadComplete = missingFields.length === 0;
const transcript = [...(source.history || []), { role: 'user', content: source.message }, { role: 'assistant', content: output.reply || '' }];
return [{ json: {
  sessionId: source.sessionId,
  reply: output.reply || 'Hello! What service are you looking for?',
  lead: {
    name: lead.name || '',
    phone: lead.phone || '',
    email: lead.email || '',
    service: lead.service || '',
    notes: lead.notes || `Website chatbot session ${source.sessionId}`
  },
  transcript,
  leadComplete,
  leadCaptured: false,
  missingFields
}}];

const parsed = $('Normalize Agent Output').first().json;
const created = $input.first().json;
return [{ json: { reply: 'Thank you. Our team will follow back soon.', leadCaptured: true, lead: created.lead || null, missingFields: [] } }];

const item = $input.first().json;
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const candidates = [];
const seen = new Set();
const queue = [item];
while (queue.length) {
  const value = queue.shift();
  if (!isObject(value) || seen.has(value)) continue;
  seen.add(value);
  candidates.push(value);
  for (const key of ['body', 'call', 'data']) {
    if (isObject(value[key])) queue.push(value[key]);
  }
}

const metadataObjects = candidates
  .map((value) => value.metadata)
  .filter(isObject);
const firstMetadataValue = (key) => {
  for (const metadata of metadataObjects) {
    const value = metadata[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value).trim();
    }
  }
  return '';
};

const callPurpose = firstMetadataValue('call_purpose');
const metadataSource = firstMetadataValue('source');
const shouldSkipVoiceLead =
  callPurpose === 'appointment_booking_callback' ||
  metadataSource === 'crm_followup_callback';

const body = isObject(item.body) ? item.body : item;
const call = candidates.find((value) =>
  value.call_id !== undefined ||
  value.transcript !== undefined ||
  value.call_analysis !== undefined ||
  value.from_number !== undefined
) || body;
const analysis = call.call_analysis || body.call_analysis || {};
const custom = analysis.custom_analysis_data || call.custom_analysis_data || body.custom_analysis_data || {};
const transcript = call.transcript || body.transcript || '';
const callerPhone = call.from_number || body.from_number || custom.patient_phone || custom.phone || '';
const known = {
  name: custom.patient_name || custom.name || '',
  phone: custom.patient_phone || custom.phone || callerPhone,
  email: custom.patient_email || custom.email || '',
  service: custom.service || custom.dental_service || '',
};
const websiteContext = 'Clinic name: Pearl Dental Studio. Services: Dental Implants, Teeth Whitening, Braces, Root Canal, Dental Fillings, Bonding. Goal: extract dental lead data from a Retell AI voice call. Required lead fields: name, email, phone, service. Do not save a lead without email.';
const agentInput = 'Extract one dental lead from this Retell voice call. Return ONLY valid JSON text with no markdown. Allowed service values: Dental Fillings, Root Canal, Teeth Whitening, Bonding, Dental Implants, Braces. If email is missing, leadComplete must be false and missingFields must include email.\n\nKnown structured data:\n' + JSON.stringify(known) + '\n\nCall summary:\n' + (analysis.call_summary || body.call_summary || '') + '\n\nTranscript:\n' + transcript + '\n\nWebsite information:\n' + websiteContext + '\n\nJSON shape: {"lead":{"name":"","phone":"","email":"","service":"","notes":""},"callSummary":"","leadComplete":false,"missingFields":["email"]}';
return [{ json: {
  agentInput,
  callPurpose,
  metadataSource,
  shouldSkipVoiceLead,
  rawPayload: body,
  callId: call.call_id || body.call_id || body.callId || '',
  fromNumber: call.from_number || body.from_number || '',
  toNumber: call.to_number || body.to_number || '',
  callStatus: call.call_status || body.call_status || body.event || '',
  transcript,
  recordingUrl: call.recording_url || body.recording_url || '',
  startedAt: call.start_timestamp ? new Date(call.start_timestamp).toISOString() : (call.started_at || body.started_at || null),
  endedAt: call.end_timestamp ? new Date(call.end_timestamp).toISOString() : (call.ended_at || body.ended_at || null),
  durationSeconds: call.duration_ms ? Math.round(call.duration_ms / 1000) : (call.duration_seconds || body.duration_seconds || null),
  userSentiment: analysis.user_sentiment || '',
  callSuccessful: analysis.call_successful,
  customAnalysisData: custom,
  baseSummary: analysis.call_summary || body.call_summary || ''
}}];

const source = $('Prepare Voice Agent Input').first().json;
let raw = $input.first().json.output || '{}';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.replace(/```json|```/g, '').trim();
let output;
try { output = JSON.parse(raw); } catch (error) { output = { lead: {}, callSummary: source.baseSummary || '', leadComplete: false, missingFields: ['email'] }; }
const lead = output.lead || {};
const required = ['name', 'phone', 'email', 'service'];
const missingFields = required.filter((field) => !String(lead[field] || '').trim());
const leadComplete = missingFields.length === 0;
return [{ json: {
  callId: source.callId,
  name: lead.name || '',
  phone: lead.phone || source.fromNumber || '',
  email: lead.email || '',
  service: lead.service || '',
  notes: lead.notes || ('Retell voice call ' + (source.callId || '')),
  transcript: source.transcript,
  callSummary: output.callSummary || source.baseSummary || '',
  recordingUrl: source.recordingUrl,
  fromNumber: source.fromNumber,
  toNumber: source.toNumber,
  callStatus: source.callStatus,
  durationSeconds: source.durationSeconds,
  startedAt: source.startedAt,
  endedAt: source.endedAt,
  userSentiment: source.userSentiment,
  callSuccessful: source.callSuccessful,
  customAnalysisData: source.customAnalysisData,
  rawPayload: source.rawPayload,
  leadComplete,
  missingFields
}}];

const triggerItem = $('Receive Voice Call Analysis').first().json;
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const rawPayload = isObject(triggerItem.body) ? triggerItem.body : triggerItem;

const candidates = [];
const seen = new Set();
const queue = [rawPayload];
while (queue.length) {
  const value = queue.shift();
  if (!isObject(value) || seen.has(value)) continue;
  seen.add(value);
  candidates.push(value);
  for (const key of ['body', 'data', 'call']) {
    if (isObject(value[key])) queue.push(value[key]);
  }
}

const firstValue = (keys, sources = candidates) => {
  for (const key of keys) {
    for (const source of sources) {
      if (!isObject(source)) continue;
      const value = source[key];
      if (value !== undefined && value !== null && value !== '') return value;
    }
  }
  return undefined;
};

const metadataObjects = candidates.map((value) => value.metadata).filter(isObject);
const analysisObjects = candidates
  .map((value) => value.call_analysis || value.callAnalysis)
  .filter(isObject);
const customObjects = [
  ...analysisObjects.map((value) => value.custom_analysis_data || value.customAnalysisData),
  ...candidates.map((value) => value.custom_analysis_data || value.customAnalysisData),
].filter(isObject);

const metadataValue = (keys) => firstValue(keys, metadataObjects);
const analysisValue = (keys) => firstValue(keys, analysisObjects);
const customValue = (keys) => firstValue(keys, customObjects);
const callValue = (keys) => firstValue(keys, candidates);

const toIso = (value) => {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number' || /^\d+(\.\d+)?$/.test(String(value))) {
    const number = Number(value);
    const milliseconds = number < 100000000000 ? number * 1000 : number;
    const date = new Date(milliseconds);
    return Number.isNaN(date.getTime()) ? null : date.toISOString();
  }
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : date.toISOString();
};

const fromNumber = callValue(['from_number', 'fromNumber']) || '';
const toNumber = callValue(['to_number', 'toNumber']) || '';
const startedRaw = callValue(['start_timestamp', 'startTimestamp', 'started_at', 'startedAt']);
const endedRaw = callValue(['end_timestamp', 'endTimestamp', 'ended_at', 'endedAt']);
const durationMs = callValue(['duration_ms', 'durationMs']);
const explicitDurationSeconds = callValue(['duration_seconds', 'durationSeconds']);
let durationSeconds = explicitDurationSeconds === undefined ? null : Number(explicitDurationSeconds);
if (!Number.isFinite(durationSeconds)) durationSeconds = null;
if (durationSeconds === null && durationMs !== undefined && Number.isFinite(Number(durationMs))) {
  durationSeconds = Math.round(Number(durationMs) / 1000);
}
if (durationSeconds === null && startedRaw !== undefined && endedRaw !== undefined) {
  const startedMs = new Date(toIso(startedRaw)).getTime();
  const endedMs = new Date(toIso(endedRaw)).getTime();
  if (Number.isFinite(startedMs) && Number.isFinite(endedMs) && endedMs >= startedMs) {
    durationSeconds = Math.round((endedMs - startedMs) / 1000);
  }
}

const successfulRaw = analysisValue(['call_successful', 'callSuccessful']) ?? callValue(['call_successful', 'callSuccessful']);
let callSuccessful = successfulRaw;
if (typeof successfulRaw === 'string') {
  if (successfulRaw.toLowerCase() === 'true') callSuccessful = true;
  else if (successfulRaw.toLowerCase() === 'false') callSuccessful = false;
}

const customAnalysisData = customObjects[0] || {};

return [{ json: {
  leadId: String(metadataValue(['lead_id', 'leadId']) || ''),
  callId: String(callValue(['call_id', 'callId']) || ''),
  phone: String(
    metadataValue(['patient_phone', 'phone', 'phone_number']) ||
    customValue(['patient_phone', 'patientPhone', 'phone', 'phone_number']) ||
    toNumber ||
    fromNumber ||
    ''
  ),
  transcript: callValue(['transcript']) || '',
  callSummary: analysisValue(['call_summary', 'callSummary']) ?? callValue(['call_summary', 'callSummary']) ?? '',
  recordingUrl: callValue(['recording_url', 'recordingUrl']) || '',
  fromNumber: String(fromNumber),
  toNumber: String(toNumber),
  callStatus: String(callValue(['call_status', 'callStatus', 'event']) || ''),
  durationSeconds,
  startedAt: toIso(startedRaw),
  endedAt: toIso(endedRaw),
  userSentiment: analysisValue(['user_sentiment', 'userSentiment']) ?? callValue(['user_sentiment', 'userSentiment']) ?? '',
  callSuccessful: callSuccessful ?? null,
  customAnalysisData,
  rawPayload,
} }];
